"""Explicit boundary: model predictions are inputs, not generated by RAG."""
from typing import Literal
from pydantic import BaseModel, ConfigDict, Field, model_validator

ATTACK_CLASSES = (
    "Analysis", "Backdoor", "DoS", "Exploits", "Fuzzers",
    "Generic", "Normal", "Reconnaissance", "Shellcode", "Worms",
)


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)


class Detection(StrictModel):
    attack_class: Literal[
        "Analysis", "Backdoor", "DoS", "Exploits", "Fuzzers",
        "Generic", "Normal", "Reconnaissance", "Shellcode", "Worms"
    ]
    confidence: float = Field(ge=0, le=1)
    model_name: str = Field(min_length=1, max_length=120)
    # Model confidence is NOT proof, and may be uncalibrated.


class Forecast(StrictModel):
    horizon_minutes: int = Field(ge=1, le=1440)
    probability: float = Field(ge=0, le=1)
    target: Literal["any_attack", "specific_attack"]
    attack_class: str | None = Field(default=None, max_length=60)
    model_name: str = Field(min_length=1, max_length=120)

    @model_validator(mode="after")
    def validate_target(self):
        if self.target == "any_attack" and self.attack_class is not None:
            raise ValueError("An any_attack forecast must not specify an attack_class")
        if self.target == "specific_attack" and self.attack_class not in (set(ATTACK_CLASSES) - {"Normal"}):
            raise ValueError("A specific_attack forecast requires a valid non-Normal class")
        return self




class HorizonForecast(StrictModel):
    """The independent Stacked LSTM any-attack onset probabilities, not class risks."""
    h5: float = Field(ge=0, le=1)
    h10: float = Field(ge=0, le=1)
    h15: float = Field(ge=0, le=1)
    model_name: str = Field(min_length=1, max_length=120)

    @model_validator(mode="after")
    def ordered_horizons(self):
        if not self.h5 <= self.h10 <= self.h15:
            raise ValueError("H5/H10/H15 must be monotonically nondecreasing")
        return self


class ConditionalOnset(StrictModel):
    """Separate competing-risk model, conditional on onset in <=15 minutes."""
    family_if_onset: Literal["BRUTE_AUTH", "DOS_DDOS", "EXPLOIT_APP", "FUZZING", "RECON_SCAN"] | None = None
    family_probability_if_onset: float | None = Field(default=None, ge=0, le=1)
    conditional_eta_minutes: float | None = Field(default=None, ge=1, le=15)
    p_onset_within_15: float = Field(ge=0, le=1)
    conditioning_horizon_minutes: Literal[15] = 15
    model_name: str = Field(min_length=1, max_length=120)

    @model_validator(mode="after")
    def validate_conditional_estimate(self):
        if (self.family_if_onset is None) != (self.family_probability_if_onset is None):
            raise ValueError("Conditional family and its confidence must appear together")
        if self.p_onset_within_15 == 0 and (self.family_if_onset is not None or self.conditional_eta_minutes is not None):
            raise ValueError("Cannot provide conditional estimates when onset mass is zero")
        return self


class Observations(StrictModel):
    protocol: str | None = Field(default=None, max_length=25)
    destination_port: int | None = Field(default=None, ge=0, le=65535)
    flow_count: int | None = Field(default=None, ge=0)
    connection_rate_per_second: float | None = Field(default=None, ge=0)
    window_minutes: int | None = Field(default=None, ge=1, le=1440)
    notes: str | None = Field(default=None, max_length=400)


class RetrieveRequest(StrictModel):
    query: str = Field(min_length=3, max_length=750)
    attack_class: str | None = Field(default=None, max_length=60)
    top_k: int = Field(default=5, ge=1, le=12)

    @model_validator(mode="after")
    def validate_attack(self):
        if self.attack_class is not None and self.attack_class not in ATTACK_CLASSES:
            raise ValueError("Unknown attack_class")
        return self


class AnalyzeRequest(StrictModel):
    question: str = Field(min_length=3, max_length=750)
    detection: Detection | None = None
    forecast: Forecast | None = None
    forecast_bundle: HorizonForecast | None = None
    family_eta: ConditionalOnset | None = None
    observations: Observations | None = None
    top_k: int = Field(default=6, ge=1, le=10)

    @model_validator(mode="after")
    def validate_analysis_contract(self):
        if not any((self.detection, self.forecast, self.forecast_bundle)):
            raise ValueError("Supply a detection or a forecast")
        if self.forecast and self.forecast_bundle:
            raise ValueError("Use either legacy forecast or H5/H10/H15 forecast bundle")
        if self.family_eta and not self.forecast_bundle:
            raise ValueError("A conditional estimate requires an H5/H10/H15 forecast bundle")
        return self


class Source(StrictModel):
    source_id: str
    title: str
    source_type: str
    source_url: str | None
    location: str
    attack_class: str | None
    similarity: float
    excerpt: str


class RetrieveResponse(StrictModel):
    results: list[Source]
    count: int


class LLMAnswer(BaseModel):
    """Schema used with Gemini structured generation; all fields required."""
    summary: str
    explanation: str
    investigation_steps: list[str]
    limitations: list[str]
    cited_source_ids: list[str]


class AnalyzeResponse(StrictModel):
    summary: str
    explanation: str
    investigation_steps: list[str]
    limitations: list[str]
    cited_source_ids: list[str]
    sources: list[Source]
    warnings: list[str]
    model_name: str
